// 6. Quick Reference — Common DQL Patterns
fetch logs, from:-1h
| summarize c = count(), by:{sumo.source_category}
| sort c desc

// Top errors by host
// status == "ERROR" covers ERROR, SEVERE, CRITICAL, ALERT, FATAL and EMERGENCY; loglevel == "ERROR" misses SEVERE.
fetch logs, from:-1h
| filter sumo.source_category == "prod/api"
| filter status == "ERROR"
| summarize c = count(), by:{host.name}
| sort c desc
| limit 10

// Latency percentiles
fetch logs, from:-1h
| filter sumo.source_category == "prod/api"
| parse content, "LD? 'latency=' INT:latency"
| summarize {
p50 = percentile(latency, 50),
p95 = percentile(latency, 95),
p99 = percentile(latency, 99)
}, by:{http.path}

// Pattern when you need to filter/sort after makeTimeseries
timeseries avg_cpu = avg(dt.host.cpu.usage), from:-1h, by:{dt.entity.host}
| fieldsAdd max_cpu = arrayMax(avg_cpu)
| filter max_cpu > 80
| sort max_cpu desc

// Lookup for enrichment
//
// Corrected 08/12/2026: `dt.tags.<name>` is not a field. Entity tags are a single `tags` field
// holding an ARRAY of "key:value" strings, so a tag is matched with an iterative expression —
// iAny(startsWith(tags[], "team:")) — not addressed as a nested field. The old cell failed with
// FIELD_DOES_NOT_EXIST. Pass the whole `tags` array through the lookup and read it downstream.
// Join on the host entity ID. `host.name` is not the host entity's name, so a
// host.name → entity.name join matches no host and leaves `tags` empty.
fetch logs, from:-1h
| filter sumo.source_category == "prod/api"
| summarize c = count(), by:{dt.entity.host}
| lookup [fetch dt.entity.host, from:-7d
| fields id, entity.name, tags],
sourceField:dt.entity.host, lookupField:id,
fields:{entity.name, tags}
